def _unique_strings(items):
    seen, result = set(), []
    for item in items:
        if item in seen: continue
        seen.add(item)
        result.append(item)
    return result

# %% ../nbs/07_mcp.ipynb #362e0a70
def _notebook_paths_from_text(text):
    return _unique_strings(re.findall(r"(?<![\w.-])(?:[~./A-Za-z0-9_-]+\.ipynb)", text or ""))

